def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Try to get the underlying data container
        data_container = getattr(self, "_data", None)
        if isinstance(data_container, dict):
            return list(data_container.keys())
        # Fallback to the instance's __dict__ if available
