        if mode is None:
            mode = "WRITE"
        elif mode not in ("READ", "WRITE"):
            raise ValueError(f"mode must be 'READ' or 'WRITE', got {mode!r}")

        # Validate bookmarks
        if bookmarks is None:
            bookmarks = []
        else:
            try:
                iter(bookmarks)
            except TypeError:
                raise TypeError("bookmarks must be an iterable of strings")
            # Ensure each bookmark is a string
            for bm in bookmarks:
                if not isinstance(bm, str):
                    raise TypeError(f"bookmark {bm!r} is not a string")

        # Validate metadata
        if metadata is None:
            metadata = {}
        elif not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict")

        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number (int or float)")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise TypeError("db must be a string")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError("imp_user must be a string")

        # Validate dehydration_hooks
        if dehydration_hooks is None:
            dehydration_hooks = {}
        elif not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        else:
            for typ, func in dehydration_hooks.items():
                if not isinstance(typ, type):
                    raise TypeError(f"dehydration hook key {typ!r} is not a type")
                if not callable(func):
                    raise TypeError(f"dehydration hook for {typ!r} is not callable")

        # Validate hydration_hooks
        if hydration_hooks is None:
            hydration_hooks = {}
        elif not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        else:
            for typ, func in hydration_hooks.items():
                if not isinstance(typ, type):
                    raise TypeError(f"hydration hook key {typ!r} is not a type")
                if not callable(func):
                    raise TypeError(f"hydration hook for {typ!r} is not callable")

        # Validate handlers
        for name, handler in handlers.items():
            if not callable(handler):
                raise TypeError(f"handler {name!r} is not callable")

        # Build the BEGIN message
        message = {
            "type": "BEGIN",
            "mode": mode,
            "bookmarks": list(bookmarks),
            "metadata": metadata,
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks
