        try:
            return Response(self, **handlers)
        except Exception as exc:
            raise RuntimeError("Failed to create Response object") from exc

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__qualname__ = getattr(func, "__qualname__", func.__name__)
        wrapper.__annotations__ = getattr(func, "__annotations__", {})
        wrapper.__defaults__ = getattr(func, "__defaults__", None)
        wrapper.__kwdefaults__ = getattr(func, "__kwdefaults__", None)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate input type
    if seq is None:
        raise TypeError("seq must not be None")
    if not isinstance(seq, Sequence):
        raise TypeError(f"seq must be a Sequence, got {type(seq).__name__}")
    # Validate each element is a string
    for idx, item in enumerate(seq):
        if not isinstance(item, str):
            raise TypeError(f"Element at index {idx} is not a str (got {type(item).__name__})")
    # Create a copy to avoid mutating the original sequence
    shuffled = list(seq)
    # Deterministic shuffle using a fixed seed
    try:
        import random
        rnd = random.Random(0)
        rnd.shuffle(shuffled)
    except Exception as exc:
        raise RuntimeError(f"Failed to shuffle sequence: {exc}") from exc
    return shuffled

