        # If an initial_value is provided, use it to fill existing bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if hasattr(self, "bins") and self.bins is not None:
                try:
                    n_bins = len(self.bins)
                except Exception:
                    n_bins = 0
                self.bins = [self.initial_value] * n_bins
            else:
                # No existing bins; create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # No initial_value; rely on make_bins to create bins
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError("make_bins method is not defined or not callable")
    except Exception as e:
        raise RuntimeError(f"Failed to reinitialize bins: {e}") from e

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    # Retrieve points from the graph
    try:
        points = self.points
    except AttributeError:
        raise AttributeError("The object does not have a 'points' attribute")

    # Prepare output lines
    lines = []
    if header is not None:
        lines.append(header)

    # If there are no points, return header or empty string
    if not points:
        return "\n".join(lines)

    for idx, point in enumerate(points):
        # Each point should be a tuple (coordinate, value)
        try:
            coord, value = point
        except Exception as exc:
            raise ValueError(f"Point at index {idx} is not a (coordinate, value) tuple") from exc

        # Convert coordinate to string
        if isinstance(coord, (list, tuple, set)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)

        # Convert value parts to string
        if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
            value_parts = [str(v) for v in value]
        else:
            value_parts = [str(value)]

        # Combine coordinate and value parts
        line = separator.join([coord_str] + value_parts)
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    try:
        err_indices = getattr(self, "_err_indices")
    except AttributeError:
        raise AttributeError("The object does not have an '_err_indices' attribute")
    if not isinstance(err_indices, dict):
        raise TypeError("Expected '_err_indices' to be a dict mapping coordinate names to indices")
    if coord_name not in err_indices:
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices")
    indices = err_indices[coord_name]
    if indices is None:
        return []
    if not isinstance(indices, (list, tuple)):
        raise TypeError(f"Error indices for coordinate '{coord_name}' must be a list or tuple")
    return list(indices)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to lists to allow multiple passes
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    # Basic shape checks
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("edges length must be one more than bins length")

    # Empty histogram returns zero
    if not bins_list:
        return 0.0

    # Compute bin widths
    try:
        widths = [edges_list[i + 1] - edges_list[i] for i in range(len(bins_list))]
    except Exception as exc:
        raise ValueError("edges must contain numeric values") from exc

    # Compute integral as sum of bin value times width
    try:
        total = sum(b * w for b, w in zip(bins_list, widths))
    except Exception as exc:
        raise ValueError("bins must contain numeric values") from exc

    return float(total)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Helper to safely check isinstance when the class may not be defined
    def _safe_isinstance(obj, cls_name):
        try:
            cls = globals()[cls_name]
        except KeyError:
            return False
        return isinstance(obj, cls)

    # Check if seq itself is a FillRequest
    if _safe_isinstance(seq, "FillRequest"):
        return True

    # Check if seq is a SourceSequence (which should return False)
    if _safe_isinstance(seq, "SourceSequence"):
        return False

    # Avoid treating strings or bytes as sequences of elements
    if isinstance(seq, (str, bytes)):
        return False

    # Try iterating over seq to find a FillRequest element
    try:
        for item in seq:
            if _safe_isinstance(item, "FillRequest"):
                return True
    except Exception:
        # seq is not iterable or some other error occurred
        return False

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'compute'))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if weight is None:
        weight = 1
    if not isinstance(weight, (int, float, complex)):
        raise TypeError(f"weight must be a numeric scalar, got {type(weight).__name__}")
    # Convert coord to a list
    try:
        coord = list(coord)
    except Exception as e:
        raise ValueError(f"coord must be an iterable, got {coord}") from e
    # Retrieve edges
    try:
        edges = self._edges
    except AttributeError as e:
        raise AttributeError("Histogram object has no _edges attribute") from e
    # Determine dimensionality
    if isinstance(edges, (list, tuple)):
        ndim = len(edges)
        edges_list = list(edges)
    else:
        ndim = 1
        edges_list = [edges]
    if len(coord) != ndim:
        raise ValueError(f"Coordinate dimension {len(coord)} does not match histogram dimension {ndim}")
    # Find bin indices
    bin_indices = []
    for dim, (edge, c) in enumerate(zip(edges_list, coord)):
        try:
            edge_arr = np.asarray(edge)
        except Exception as e:
            raise ValueError(f"Edge for dimension {dim} is not array-like") from e
        idx = np.searchsorted(edge_arr, c, side='right') - 1
        if idx < 0 or idx >= len(edge_arr) - 1:
            # Outside histogram edges
            return
        bin_indices.append(idx)
    # Increment the bin
    try:
        self._bins[tuple(bin_indices)] += weight
    except Exception as e:
        raise RuntimeError("Failed to increment histogram bin") from e

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    if not isinstance(labels, dict):
        raise ValidationError([{"labels": "labels must be a dict"}])

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            if not LABEL_KEY_REGEX.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex {LABEL_KEY_REGEX.pattern}"}
                )

        # Helper to validate a single value
        def _validate_value(v):
            if not isinstance(v, (str, bytes)):
                errors.append({str(v): "expected string or bytes-like object"})
            else:
                if not LABEL_VALUE_REGEX.match(v):
                    errors.append(
                        {v: f"Label value '{v}' does not match the regex {LABEL_VALUE_REGEX.pattern}"}
                    )

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for v in value:
                _validate_value(v)
        else:
            _validate_value(value)

    if errors:
        raise ValidationError(errors)

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    class ValidationError(Exception):
        pass

    if not isinstance(key, str):
        raise ValidationError("Key must be a string")
    if not key:
        raise ValidationError("Key cannot be empty")

    # Define allowed characters: letters, digits, hyphen, underscore, period
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")
    if not all(ch in allowed_chars for ch in key):
        raise ValidationError("Key contains invalid characters")

    # Optional: enforce that the key starts with a letter
    if not key[0].isalpha():
        raise ValidationError("Key must start with a letter")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer schema dictionary from a Kubernetes resource dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if manifest_dict is None:
        return {}
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected dict for manifest_dict, got {type(manifest_dict).__name__}")

    # Identifying fields that should be copied verbatim when first_level is True
    identifying_fields = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            # Copy the value as-is for identifying fields
            result[key] = value
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve lists unchanged; they will be processed by a separate helper
            result[key] = value
        else:
            # Replace non-dict/list values with None
            result[key] = None

    return result

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    # Basic validation of the input
    if app is None:
        raise TypeError("app must not be None")

    try:
        # Retrieve the manifest list
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("app.spec is missing")

        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("app.spec.manifest is missing")

        # Retrieve any custom observer schemas that may already exist
        custom_schemas = getattr(spec, "observer_schema", {})
        if not isinstance(custom_schemas, dict):
            # If it's not a dict, treat it as empty
            custom_schemas = {}

        default_schemas = {}

        for resource in manifest:
            if not isinstance(resource, dict):
                # Skip non-dict entries
                continue

            kind = resource.get("kind")
            if not kind:
                # Skip resources without a kind
                continue

            # Skip kinds that already have a custom schema
            if kind in custom_schemas:
                continue

            # Generate a very simple default schema
            # This can be extended to include more fields as needed
            schema = {
                "metadata": {
                    "name": "",
                    "namespace": ""
                },
                "status": {}
            }

            # If the same kind appears multiple times, keep the first generated schema
            if kind not in default_schemas:
                default_schemas[kind] = schema

        return default_schemas

    except Exception as exc:
        # Re-raise with a more informative message
        raise RuntimeError(f"Failed to generate default observer schema: {exc}") from exc

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        parts = []

        # Validity
        if hasattr(self, 'valid') and isinstance(self.valid, bool):
            parts.append('Valid' if self.valid else 'Invalid')
        elif hasattr(self, 'is_valid') and isinstance(self.is_valid, bool):
            parts.append('Valid' if self.is_valid else 'Invalid')
        elif hasattr(self, 'status') and isinstance(self.status, str):
            parts.append(self.status)

        # Errors
        if hasattr(self, 'errors'):
            errors = self.errors
            if isinstance(errors, (list, tuple, set)):
                parts.append(f'Errors: {len(errors)}')
            elif isinstance(errors, int):
                parts.append(f'Errors: {errors}')
            elif errors is not None:
                parts.append(f'Errors: {errors}')
        elif hasattr(self, 'error_count') and isinstance(self.error_count, int):
            parts.append(f'Errors: {self.error_count}')

        # Warnings
        if hasattr(self, 'warnings'):
            warnings = self.warnings
            if isinstance(warnings, (list, tuple, set)):
                parts.append(f'Warnings: {len(warnings)}')
            elif isinstance(warnings, int):
                parts.append(f'Warnings: {warnings}')
            elif warnings is not None:
                parts.append(f'Warnings: {warnings}')
        elif hasattr(self, 'warning_count') and isinstance(self.warning_count, int):
            parts.append(f'Warnings: {self.warning_count}')

        # Message
        if hasattr(self, 'message') and isinstance(self.message, str):
            parts.append(f'Message: {self.message}')

        # Default if nothing found
        if not parts:
            parts.append('No status available')

        status = ' | '.join(parts)
        return f"{prefix} {status}".strip() if prefix else status
    except Exception as e:
        return f"{prefix} Error generating status: {e}".strip() if prefix else f"Error generating status: {e}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Normalize prefix
    if prefix is None:
        prefix_str = ''
    else:
        try:
            prefix_str = str(prefix)
        except Exception:
            raise TypeError("prefix must be convertible to string") from None

    # Locate a validation log attribute
    log = None
    for attr in ('log', 'validation_log', 'validation_log_entries', 'entries', 'messages', 'log_entries'):
        if hasattr(self, attr):
            log = getattr(self, attr)
            break

    # No log found
    if log is None:
        return prefix_str + 'No validation log available.'

    # Build string representation
    lines = []

    if isinstance(log, str):
        lines = [log]
    elif isinstance(log, dict):
        if not log:
            lines = ['No validation log entries.']
        else:
            for key, value in log.items():
                try:
                    key_str = str(key)
                except Exception:
                    key_str = '<unrepresentable key>'
                if isinstance(value, (list, tuple, set, frozenset)):
                    for v in value:
                        try:
                            lines.append(f"{key_str}: {v}")
                        except Exception:
                            lines.append(f"{key_str}: <unrepresentable value>")
                else:
                    try:
                        lines.append(f"{key_str}: {value}")
                    except Exception:
                        lines.append(f"{key_str}: <unrepresentable value>")
    else:
        try:
            iterator = iter(log)
        except TypeError:
            try:
                lines = [str(log)]
            except Exception:
                lines = ['<unrepresentable log>']
        else:
            for entry in iterator:
                try:
                    lines.append(str(entry))
                except Exception:
                    lines.append('<unrepresentable entry>')

    if not lines:
        lines = ['No validation log entries.']

    prefixed_lines = [prefix_str + line for line in lines]
    return '\n'.join(prefixed_lines)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check for inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine the specification version to use for validation
    spec_version = getattr(self, "spec_version", None)
    if spec_version is None:
        raise AttributeError("The object must have a 'spec_version' attribute")

    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Map known type values to spec versions; extend as needed
            type_to_version = {
                "v1": "1.0",
                "v2": "2.0",
                "legacy": "0.9",
            }
            # Use the mapped version if available; otherwise keep the default
            spec_version = type_to_version.get(type_val, spec_version)

    # Define required keys and simple type checks based on the spec version
    if spec_version == "1.0":
        required_keys = {"name": str, "items": list}
    elif spec_version == "2.0":
        required_keys = {"name": str, "items": list, "metadata": dict}
    else:
        # Default to a minimal set for unknown versions
        required_keys = {"name": str, "items": list}

    # Validate presence and type of required keys
    for key, expected_type in required_keys.items():
        if key not in inventory:
            raise ValueError(f"Missing required key '{key}' for spec_version {spec_version}")
        if not isinstance(inventory[key], expected_type):
            raise TypeError(f"Key '{key}' must be of type {expected_type.__name__}")

    # Additional optional checks can be added here if needed

    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is an InventoryValidator instance
        if not isinstance(prior, type(self)):
            raise TypeError(
                f"prior must be an instance of {type(self).__name__}, "
                f"got {type(prior).__name__}"
            )

        # Check that both objects have a 'version' attribute
        if not hasattr(self, "version"):
            raise AttributeError(f"{type(self).__name__} instance missing 'version' attribute")
        if not hasattr(prior, "version"):
            raise AttributeError(f"prior instance missing 'version' attribute")

        # Compare versions: prior must be strictly older
        try:
            if prior.version >= self.version:
                raise ValueError(
                    f"prior.version ({prior.version}) must be less than "
                    f"self.version ({self.version})"
                )
        except TypeError:
            # If versions are not comparable, raise a clear error
            raise TypeError(
                f"Cannot compare versions: prior.version={prior.version!r}, "
                f"self.version={self.version!r}"
            )

        # If inventories contain items, ensure prior's items are a subset of self's
        if hasattr(self, "items") and hasattr(prior, "items"):
            # Assume items are dicts or sets; convert to set of keys for comparison
            try:
                self_keys = set(self.items.keys()) if isinstance(self.items, dict) else set(self.items)
                prior_keys = set(prior.items.keys()) if isinstance(prior.items, dict) else set(prior.items)
            except Exception as exc:
                raise ValueError(
                    f"Error extracting items from inventories: {exc}"
                ) from exc

            if not prior_keys.issubset(self_keys):
                missing = prior_keys - self_keys
                raise ValueError(
                    f"prior inventory contains items not present in current inventory: {missing}"
                )

        # All checks passed
        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")

    result = {}
    found = False

    try:
        if isinstance(inventory, dict):
            # inventory expected to be {version: {logical_path: content_file}}
            for v, mapping in inventory.items():
                try:
                    if v == version:
                        found = True
                    if v < version:
                        continue
                except Exception:
                    # If versions are not comparable, skip comparison
                    continue
                if not isinstance(mapping, dict):
                    continue
                for logical_path, content_file in mapping.items():
                    if logical_path is None or content_file is None:
                        continue
                    result.setdefault(logical_path, set()).add(content_file)
        else:  # list of entries
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                entry_version = entry.get("version")
                if entry_version is None:
                    continue
                try:
                    if entry_version == version:
                        found = True
                    if entry_version < version:
                        continue
                except Exception:
                    continue
                logical_path = entry.get("logical_path")
                content_file = entry.get("content_file")
                if logical_path is None or content_file is None:
                    continue
                result.setdefault(logical_path, set()).add(content_file)

        if not found:
            raise ValueError(f"Version {version!r} not found in inventory")
    except Exception as exc:
        raise RuntimeError(f"Error processing inventory: {exc}") from exc

    return result

def add_rendition(self, lang, file_path):
    """
    Adds a rendition for the given language.
    """
    # Validate inputs
    if not isinstance(lang, str) or not lang.strip():
        raise ValueError("lang must be a non-empty string")
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("file_path must be a non-empty string")

    try:
        # Ensure the renditions attribute exists and is a dict
        if not hasattr(self, 'renditions'):
            self.renditions = {}
        if not isinstance(self.renditions, dict):
            raise TypeError("renditions attribute must be a dict")

        # Add or update the rendition
        self.renditions[lang] = file_path
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError for clarity
        raise RuntimeError(f"Failed to add rendition: {exc}") from exc

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    if not zip_path:
        raise ValueError("zip_path cannot be empty")

    import os
    import zipfile

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue
                file_name = info.filename
                # Determine the base name (without extension)
                base_name = os.path.splitext(os.path.basename(file_name))[0]
                if base_name not in result:
                    result[base_name] = {}
                try:
                    data = zf.read(info)
                except Exception:
                    # Skip files that cannot be read
                    continue
                result[base_name][file_name] = data
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc
    except OSError as exc:
        # Handle other OS-related errors (e.g., permission issues)
        raise OSError(f"Error accessing zip file '{zip_path}': {exc}") from exc

    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError("Error processing content") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    try:
        for xpath in pubdate_xpaths:
            try:
                result = node.xpath(xpath)
                if result:
                    if isinstance(result, list):
                        return result[0]
                    else:
                        return result
            except Exception:
                continue
    except Exception:
        return None
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    # Helper to format objects recursively
    def _format(obj, level, visited):
        # Avoid infinite recursion
        obj_id = id(obj)
        if obj_id in visited:
            return "<Recursion>"
        visited.add(obj_id)

        # Primitive types
        if isinstance(obj, (str, int, float, bool, type(None))):
            return repr(obj)

        # Dictionaries
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in obj.items():
                key_repr = repr(k)
                val_repr = _format(v, level + 1, visited)
                items.append(" " * ((level + 1) * indent) + f"{key_repr}: {val_repr}")
            return "{\n" + ",\n".join(items) + "\n" + " " * (level * indent) + "}"

        # Lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                return type(obj).__name__ + "()"
            items = []
            for item in obj:
                items.append(" " * ((level + 1) * indent) + _format(item, level + 1, visited))
            if isinstance(obj, list):
                opening, closing = "[\n", "]"
            elif isinstance(obj, tuple):
                opening, closing = "(\n", ")"
            else:  # set
                opening, closing = "{\n", "}"
            return opening + ",\n".join(items) + "\n" + " " * (level * indent) + closing

        # Custom objects
        if hasattr(obj, "__dict__"):
            return f"{obj.__class__.__name__}(" + _format(obj.__dict__, level, visited) + ")"
        if hasattr(obj, "__slots__"):
            slots = {slot: getattr(obj, slot) for slot in obj.__slots__ if hasattr(obj, slot)}
            return f"{obj.__class__.__name__}(" + _format(slots, level, visited) + ")"

        # Fallback
        return repr(obj)

    try:
        result = _format(self, 0, set())
        if debug:
            result += f"\n# Debug: type={type(self).__name__}"
        return result
    except Exception as e:
        return f"<Error pretty printing: {e}>"

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate hook
    if hook is None:
        raise ValueError("Hook cannot be None")
    # Ensure registry exists and is a dict
    if not hasattr(self, "_hook_registry"):
        self._hook_registry = {}
    if not isinstance(self._hook_registry, dict):
        raise TypeError("Hook registry must be a dictionary")
    # Ensure hook key exists
    try:
        if hook not in self._hook_registry:
            self._hook_registry[hook] = []
    except TypeError as e:
        raise TypeError(f"Hook {hook!r} is not hashable and cannot be used as a key") from e

    def decorator(func):
        if not callable(func):
            raise TypeError(f"Listener {func!r} is not callable")
        # Register the function
        try:
            listeners = self._hook_registry[hook]
            if func not in listeners:
                listeners.append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register listener for hook {hook!r}") from e
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            try:
                result = namefunc(*args, **kwargs)
            except Exception:
                # propagate any exception from the original function
                raise
            # In Python 2, str is a byte string, unicode is a Unicode string
            if isinstance(result, str):
                return result
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except Exception:
                    # If encoding fails, return the original value
                    return result
            # If result is not a string type, return it unchanged
            return result
        return wrapper
    else:
        # In Python 3, no conversion is needed
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try to get the version of the current package or module
        from importlib.metadata import version, PackageNotFoundError
        # Prefer the package name if available
        pkg_name = __package__ or __name__
        # If the name is a module name like '__main__', it may not be a package
        # In that case, attempt to get the version of the module's distribution
        try:
            ver = version(pkg_name)
        except PackageNotFoundError:
            # Fallback: try to get the version of the module's distribution
            ver = version(__name__)
        return {"version": ver}
    except Exception:
        # If any error occurs (e.g., package not found, import error), return a default
        return {"version": "0.0.0"}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    if pieces is None:
        return ''
    # Handle string pieces as a single part
    if isinstance(pieces, str):
        parts = [pieces]
    else:
        try:
            iterable = list(pieces)
        except TypeError:
            raise TypeError("pieces must be an iterable")
        parts = [str(p) for p in iterable if p is not None]
    if not parts:
        return ''
    if style in ('semver', 'full'):
        return '.'.join(parts)
    elif style == 'short':
        return '.'.join(parts[:2]) if len(parts) >= 2 else '.'.join(parts)
    elif style == 'pep440':
        # Attach pre-release identifiers to the previous part
        result = []
        prefixes = ('a', 'b', 'rc', 'pre', 'post', 'dev')
        for part in parts:
            if any(part.lower().startswith(prefix) for prefix in prefixes):
                if result:
                    result[-1] += part
                else:
                    result.append(part)
            else:
                result.append(part)
        return '.'.join(result)
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        for item in pieces:
            if '+' in str(item):
                return '.'
        return '+'
    except Exception:
        # If pieces is not iterable or any error occurs, default to '+'
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    import os

    # Normalize commands
    if isinstance(commands, str):
        # Split a single string into a list of arguments
        commands = shlex.split(commands)
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    # Ensure all elements are strings
    commands = [str(c) for c in commands]

    # Normalize args
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list/tuple of strings or None")
    args = [str(a) for a in args]

    # Build the full command list
    cmd = list(commands) + list(args)
    if not cmd:
        raise ValueError("No command specified")

    # Prepare environment
    env_dict = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        env_dict.update({str(k): str(v) for k, v in env.items()})

    # Prepare stderr handling
    # We always capture stderr to allow error reporting, but we can hide it from output
    stderr_capture = subprocess.PIPE

    if verbose:
        # Show the command being executed
        print("Running command:", " ".join(shlex.quote(part) for part in cmd))

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_dict,
            capture_output=True,
            text=True,
            check=True,
            stderr=stderr_capture,
        )
        if verbose:
            if result.stdout:
                print(result.stdout, end="")
            if not hide_stderr and result.stderr:
                print(result.stderr, end="")
        return result.stdout
    except subprocess.CalledProcessError as e:
        # Build a helpful error message
        error_msg = f"Command '{' '.join(shlex.quote(part) for part in cmd)}' exited with status {e.returncode}"
        if e.stdout:
            error_msg += f"\nStdout:\n{e.stdout}"
        if e.stderr:
            error_msg += f"\nStderr:\n{e.stderr}"
        raise RuntimeError(error_msg) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command '{' '.join(cmd)}': {e}") from e

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise ValueError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise ValueError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise ValueError("show_warnings must be a boolean")

    # Ensure storage_root attribute exists
    if not hasattr(self, 'storage_root'):
        raise AttributeError("Instance does not have 'storage_root' attribute")
    root = self.storage_root
    if not isinstance(root, str):
        raise ValueError("storage_root must be a string path")

    num_objects = 0
    good_objects = 0

    # Walk through directory
    try:
        for dirpath, dirnames, filenames in os.walk(root):
            for filename in filenames:
                # Skip digest files
                if check_digests and filename.endswith('.sha256'):
                    continue
                file_path = os.path.join(dirpath, filename)
                num_objects += 1
                is_valid = True
                # Validate object: check readable
                if validate_objects:
                    try:
                        with open(file_path, 'rb') as f:
                            f.read(1)
                    except Exception as e:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: Cannot read file {file_path}: {e}")
                # Check digest
                if check_digests:
                    digest_path = file_path + '.sha256'
                    if os.path.exists(digest_path):
                        try:
                            with open(file_path, 'rb') as f:
                                data = f.read()
                            actual_digest = hashlib.sha256(data).hexdigest()
                            with open(digest_path, 'r') as df:
                                expected_digest = df.read().strip()
                            if actual_digest != expected_digest:
                                is_valid = False
                                if show_warnings:
                                    print(f"Warning: Digest mismatch for {file_path}")
                        except Exception as e:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: Error checking digest for {file_path}: {e}")
                if is_valid:
                    good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Warning: Error walking directory {root}: {e}")
        # Return counts so far in case of error
    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return {}

    # Load the root inventory once
    root_inventory_path = os.path.join(self.root_dir, "inventory.json")
    if not os.path.exists(root_inventory_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load root inventory: {exc}")

    # Store differences per version
    differences = {}

    for version in version_dirs:
        # Construct path to the inventory for this version
        inv_path = os.path.join(self.root_dir, str(version), "inventory.json")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Inventory missing for version {version} at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory for version {version}: {exc}")

        # Compare digests against the root inventory
        diff_files = []
        for file_path, digest in inv.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is None:
                diff_files.append((file_path, "missing in root inventory"))
            elif root_digest != digest:
                diff_files.append((file_path, "digest mismatch"))

        if diff_files:
            differences[version] = diff_files

    return differences

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import fnmatch

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # List directory contents
            try:
                entries = os.listdir(path)
            except OSError as e:
                return f"Cannot list directory '{path}': {e}"

            # Find Namaste files (files starting with "0=")
            namaste_files = [e for e in entries
                             if fnmatch.fnmatch(e, "0=*") and
                             os.path.isfile(os.path.join(path, e))]

            if not namaste_files:
                return f"No Namaste file found in directory: {path}"

            # Check for 'objects' subdirectory to distinguish root
            if "objects" in entries and os.path.isdir(os.path.join(path, "objects")):
                return "root"
            else:
                return "object"

        return f"Unknown path type: {path}"
    except Exception as exc:
        return f"Error determining path type for '{path}': {exc}"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    # Recursive merge of two MappingNodes
    def merge_mapping_nodes(node1, node2):
        # Preserve the tag from the first node
        tag = getattr(node1, 'tag', None)
        # Build a dict of key -> (key_node, value_node) from node1
        merged = {}
        for k_node, v_node in getattr(node1, 'value', []):
            key = getattr(k_node, 'value', None)
            merged[key] = (k_node, v_node)
        # Merge entries from node2
        for k_node2, v_node2 in getattr(node2, 'value', []):
            key = getattr(k_node2, 'value', None)
            if key in merged:
                old_k_node, old_v_node = merged[key]
                if is_mapping_node(old_v_node) and is_mapping_node(v_node2):
                    merged[key] = (old_k_node, merge_mapping_nodes(old_v_node, v_node2))
                else:
                    merged[key] = (old_k_node, v_node2)
            else:
                merged[key] = (k_node2, v_node2)
        # Construct the merged value list preserving order
        merged_value = [pair for pair in merged.values()]
        # Instantiate a new MappingNode of the same type as node1
        return type(node1)(tag=tag, value=merged_value)

    # Validate input
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    result_dict = {}
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError('each entry must be a tuple of (key_node, value_node)')
        key_node, value_node = entry
        key = getattr(key_node, 'value', None)
        if key is None:
            raise ValueError('key_node must have a value attribute')
        if key not in result_dict:
            result_dict[key] = (key_node, value_node)
        else:
            _, existing_value = result_dict[key]
            if is_mapping_node(existing_value) and is_mapping_node(value_node):
                merged_value = merge_mapping_nodes(existing_value, value_node)
                result_dict[key] = (result_dict[key][0], merged_value)
            else:
                # Last value wins for non-mapping nodes
                result_dict[key] = (result_dict[key][0], value_node)
    # Preserve order of first occurrence
    return [(k_node, v_node) for k_node, v_node in result_dict.values()]

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # argparse.ArgumentParser instances expose a _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # Each action has an option_strings attribute containing the flags
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        return " ".join(flags)
    except Exception as exc:
        # Wrap any unexpected exception in a RuntimeError with context
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

