def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a MappingNode based on its tag
    def _is_mapping_node(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    # Recursive merge of two MappingNodes
    def _merge_mapping_nodes(node1, node2):
        # node1 and node2 are assumed to be MappingNodes
        merged_dict = {}
        # Add entries from node1
        for k_node, v_node in getattr(node1, 'value', []):
            key = getattr(k_node, 'value', None)
            merged_dict[key] = (k_node, v_node)
        # Merge entries from node2
        for k_node, v_node in getattr(node2, 'value', []):
            key = getattr(k_node, 'value', None)
            if key in merged_dict:
                existing_k_node, existing_v_node = merged_dict[key]
                if _is_mapping_node(existing_v_node) and _is_mapping_node(v_node):
                    merged_v = _merge_mapping_nodes(existing_v_node, v_node)
                    merged_dict[key] = (existing_k_node, merged_v)
                else:
                    # Last value wins
                    merged_dict[key] = (existing_k_node, v_node)
            else:
                merged_dict[key] = (k_node, v_node)
        # Build merged list preserving order of first occurrence
        merged_pairs = [(k, v) for k, (k, v) in merged_dict.items()]
        # Construct a new MappingNode with the same tag as node1
        return type(node1)(node1.tag, merged_pairs)

    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list')
    result_dict = {}
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError('each entry must be a tuple of (key_node, value_node)')
        key_node, value_node = entry
        key = getattr(key_node, 'value', None)
        if key is None:
            raise ValueError('key_node must have a value attribute')
        if key not in result_dict:
            result_dict[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = result_dict[key]
            if _is_mapping_node(existing_value_node) and _is_mapping_node(value_node):
                merged_value = _merge_mapping_nodes(existing_value_node, value_node)
                result_dict[key] = (existing_key_node, merged_value)
            else:
                # Last value wins
                result_dict[key] = (existing_key_node, value_node)
    # Return list of tuples preserving insertion order
    return [(k_node, v_node) for k_node, v_node in result_dict.values()]

