        raise ValueError("max_results must be a positive integer")

    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        raise RuntimeError(f"An error occurred while paging: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("Input must be an iterable of dictionaries") from exc

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Item at index {idx} is not a dictionary: {d!r}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as exc:
                    raise TypeError(f"Cannot sum values for key {key!r}: {exc}") from exc
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Validate input types
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    import re

    # Pattern matches {key} or <key>
    pattern = re.compile(r'\{(\w+)\}|\<(\w+)\>')

    def _replacer(match):
        # Extract the key from either group
        key = match.group(1) or match.group(2)
        if key in url_args:
            # Convert the value to string, treating None as empty string
            val = url_args[key]
            return '' if val is None else str(val)
        # If key not found, leave the placeholder unchanged
        return match.group(0)

    try:
        return pattern.sub(_replacer, url)
    except Exception as exc:
        # Wrap any unexpected error in a ValueError for clarity
        raise ValueError(f"Error replacing URL arguments: {exc}") from exc

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        s = val.strip().lower()
        return s in {"none", "null", "nil", "na", "n/a", ""}
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        # Ensure parser has the expected attribute
        actions = getattr(parser, "_actions", None)
        if actions is None:
            return ""
        flags = []
        for action in actions:
            # Optional arguments have option_strings; positional have empty list
            option_strings = getattr(action, "option_strings", [])
            if option_strings:
                flags.extend(option_strings)
            else:
                # For positional arguments, use the destination name
                dest = getattr(action, "dest", None)
                if dest:
                    flags.append(dest)
        return " ".join(flags)
    except Exception:
        # In case of any unexpected error, return an empty string
        return ""

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: Modified dictionary with the key replaced
    """
    # Basic validation
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, (int, str)):
        raise TypeError("register_number must be an int or str")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key name")

    def _recursive_replace(d):
        # Use list to avoid RuntimeError due to dict size change during iteration
        for key in list(d.keys()):
            try:
                if key == register_value:
                    # Replace key with register_number
                    d[register_number] = d[key]
                    del d[key]
                else:
                    val = d[key]
                    if isinstance(val, dict):
                        _recursive_replace(val)
                    elif isinstance(val, list):
                        for item in val:
                            if isinstance(item, dict):
                                _recursive_replace(item)
            except Exception:
                # Skip problematic entries but continue processing
                continue

    try:
        _recursive_replace(flow_params)
    except Exception as e:
        # If any unexpected error occurs, raise a RuntimeError with context
        raise RuntimeError(f"Failed to replace register key: {e}") from e

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise ValueError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    result = set()
    try:
        for sub in cls.__subclasses__():
            result.add(sub)
            result.update(subclasses(sub))
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve subclasses of {cls}") from exc
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError("string must be a str")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")

    # Validate alphabet
    if len(alphabet) == 0:
        raise ValueError("alphabet must not be empty")
    seen = set()
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise TypeError("alphabet elements must be single-character strings")
        if ch in seen:
            raise ValueError("alphabet contains duplicate characters")
        seen.add(ch)

    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    # Validate string
    if string == "":
        raise ValueError("string must not be empty")

    result = 0
    for c in string:
        if c not in char_to_value:
            raise ValueError(f"character '{c}' not in alphabet")
        result = result * base + char_to_value[c]

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Basic input validation
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise ValueError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists
    try:
        if destination_path.exists():
            if not destination_path.is_dir():
                raise ValueError(f"destination_path '{destination_path}' exists but is not a directory")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to prepare destination directory '{destination_path}': {exc}") from exc

    # Download the archive
    try:
        import requests
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(f"Failed to download archive from '{url}': {exc}") from exc

    # Write to a temporary file
    import tempfile
    temp_file = None
    try:
        temp_file = tempfile.NamedTemporaryFile(delete=False)
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                temp_file.write(chunk)
        temp_file.close()
    except Exception as exc:
        if temp_file:
            try:
                temp_file.close()
            except Exception:
                pass
        raise RuntimeError(f"Failed to write downloaded data to temporary file: {exc}") from exc

    # Extract the archive
    try:
        import tarfile
        with tarfile.open(temp_file.name, "r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except tarfile.TarError as exc:
        raise RuntimeError(f"Failed to extract archive '{temp_file.name}': {exc}") from exc
    finally:
        # Clean up temporary file
        try:
            import os
            os.remove(temp_file.name)
        except Exception:
            pass

    return destination_path

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Strip leading and trailing single or double quotes
    return name.strip('\'"')

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        if not host:
            return False
        host = host.strip()
        # Direct string checks
        if host.lower() == 'localhost':
            return True
        # IPv4 loopback
        try:
            if socket.inet_aton(host) == socket.inet_aton('127.0.0.1'):
                return True
        except OSError:
            pass
        # IPv6 loopback
        try:
            if socket.inet_pton(socket.AF_INET6, host) == socket.inet_pton(socket.AF_INET6, '::1'):
                return True
        except (OSError, AttributeError):
            pass
        # Resolve host to IP addresses
        try:
            infos = socket.getaddrinfo(host, None)
        except socket.gaierror:
            return False
        resolved_ips = set()
        for info in infos:
            addr = info[4][0]
            resolved_ips.add(addr)
            # Check if this address is loopback
            try:
                if socket.inet_aton(addr) == socket.inet_aton('127.0.0.1'):
                    return True
            except OSError:
                try:
                    if socket.inet_pton(socket.AF_INET6, addr) == socket.inet_pton(socket.AF_INET6, '::1'):
                        return True
                except (OSError, AttributeError):
                    pass
        # Get local machine IP addresses
        local_ips = []
        try:
            local_ips.extend(socket.gethostbyname_ex(socket.gethostname())[2])
        except socket.gaierror:
            pass
        try:
            local_infos = socket.getaddrinfo(socket.gethostname(), None)
            for info in local_infos:
                local_ips.append(info[4][0])
        except socket.gaierror:
            pass
        # Compare resolved IPs with local IPs
        for ip in resolved_ips:
            if ip in local_ips:
                return True
        return False
    except Exception:
        return False

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if find_paths is None:
        return []
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")
    result = []
    for p in iterator:
        if not isinstance(p, str):
            raise TypeError(f"find_paths elements must be strings, got {type(p)}")
        # Treat strings containing a scheme (e.g., 'sh:' or 'pp:') as patterns
        if re.match(r'^[a-zA-Z]+:', p):
            result.append(p)
        else:
            result.append(f'sh:**/*{p}*/**')
    return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only consider Windows environments
        if os.name != 'nt':
            return False

        # Check common environment variables set by Git Bash
        ostype = os.environ.get('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True

        msystem = os.environ.get('MSYSTEM', '').lower()
        if msystem.startswith('mingw') or msystem.startswith('msys'):
            return True

        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer representing file permissions")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Ensure parent directories exist
    dirpath = os.path.dirname(os.path.abspath(config_filename))
    if dirpath and not os.path.isdir(dirpath):
        try:
            os.makedirs(dirpath, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories '{dirpath}': {exc}") from exc

    # Check for existing file
    if os.path.exists(config_filename):
        if not overwrite:
            raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")
        # If overwrite is True, we will replace the file

    # Write the configuration
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc

    # Set file permissions
    try:
        os.chmod(config_filename, mode)
    except OSError as exc:
        # If chmod fails, we still consider the file written; log or re-raise as needed
        raise OSError(f"Failed to set permissions on '{config_filename}': {exc}") from exc

    return None

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")
    image_href = image_href.strip()
    if not image_href:
        raise ValueError("image_href cannot be empty")
    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid image_href: {image_href}") from exc
    scheme = parsed.scheme.lower()
    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme '{scheme}' in image_href: {image_href}")
    netloc = parsed.netloc
    if not netloc:
        raise ValueError(f"Missing netloc in image_href: {image_href}")
    path = parsed.path
    if not path:
        raise ValueError(f"Missing path in image_href: {image_href}")
    path = path.rstrip("/")
    if not path:
        raise ValueError(f"Missing image id in image_href: {image_href}")
    image_id = path.split("/")[-1]
    if not image_id:
        raise ValueError(f"Missing image id in image_href: {image_href}")
    use_ssl = scheme == "https"
    return image_id, netloc, use_ssl

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Determine the dumper class to use
        if dumper is None:
            dumper_cls = yaml.SafeDumper
        else:
            dumper_cls = dumper
        # Perform the dump
        s = yaml.dump(obj, Dumper=dumper_cls, allow_unicode=True)
        # In Python 2, yaml.dump returns a byte string; convert to unicode
        if isinstance(s, bytes):
            s = s.decode('utf-8')
        return s
    except yaml.YAMLError as exc:
        raise ValueError(f"YAML dump error: {exc}") from exc
    except Exception as exc:
        raise ValueError(f"Failed to dump object to YAML string: {exc}") from exc

def build_app_logger(name='app', logfile='app.log', debug=True):
    """
    General purpose application logger. Useful mainly for debugging
    """
    # Validate inputs
    try:
        if not isinstance(name, str) or not name:
            name = 'app'
        if not isinstance(logfile, str) or not logfile:
            logfile = 'app.log'
        if not isinstance(debug, bool):
            debug = True
    except Exception:
        # Fallback to defaults if any unexpected error occurs
        name = 'app'
        logfile = 'app.log'
        debug = True

    try:
        logger = logging.getLogger(name)
        logger.setLevel(logging.DEBUG if debug else logging.INFO)

        # Avoid adding duplicate handlers
        existing_handlers = {type(h).__name__: h for h in logger.handlers}

        # File handler
        if 'FileHandler' not in existing_handlers or existing_handlers['FileHandler'].baseFilename != os.path.abspath(logfile):
            # Ensure directory exists
            log_dir = os.path.dirname(os.path.abspath(logfile))
            if log_dir and not os.path.exists(log_dir):
                try:
                    os.makedirs(log_dir, exist_ok=True)
                except Exception as e:
                    # If directory creation fails, fallback to current directory
                    logfile = os.path.basename(logfile)
            file_handler = logging.FileHandler(logfile)
            file_handler.setLevel(logging.DEBUG if debug else logging.INFO)
            file_handler.setFormatter(logging.Formatter(
                "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
            ))
            logger.addHandler(file_handler)

        # Stream handler (console)
        if 'StreamHandler' not in existing_handlers:
            stream_handler = logging.StreamHandler()
            stream_handler.setLevel(logging.DEBUG if debug else logging.INFO)
            stream_handler.setFormatter(logging.Formatter(
                "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
            ))
            logger.addHandler(stream_handler)

        return logger
    except Exception as e:
        # If logger setup fails, raise a RuntimeError with details
        raise RuntimeError(f"Failed to configure logger '{name}': {e}") from e

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or list
        shape of the array to create
    dtype : `numpy.dtype` or convertible to dtype
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        Array of the specified shape and dtype.

    Raises
    ------
    ValueError
        If shape is not a tuple/list of non-negative integers or dtype is invalid.
    RuntimeError
        If array creation fails due to memory or other runtime issues.
    """
    # Validate and normalize shape
    if shape is None:
        raise ValueError("shape must not be None")
    try:
        # Accept list or tuple; convert to tuple
        shape_tuple = tuple(shape)
    except Exception as exc:
        raise ValueError(f"shape must be an iterable of integers, got {shape!r}") from exc
    if not shape_tuple:
        # Empty tuple is allowed (scalar array)
        pass
    for idx, dim in enumerate(shape_tuple):
        if not isinstance(dim, int):
            raise ValueError(f"shape dimension at index {idx} is not an integer: {dim!r}")
        if dim < 0:
            raise ValueError(f"shape dimension at index {idx} is negative: {dim}")

    # Validate and convert dtype
    if dtype is None:
        raise ValueError("dtype must not be None")
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise ValueError(f"Invalid dtype: {dtype!r}") from exc

    # Attempt to create the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except MemoryError as mem_err:
        raise RuntimeError(f"Memory allocation failed for shape {shape_tuple} and dtype {dtype_obj}") from mem_err
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input x must be a number or array-like of numbers") from e
    mu = 0.2
    sigma = 0.1
    return np.exp(-((x_arr - mu)**2) / (2 * sigma**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re, logging
    configs = {}
    errors = []
    env_pattern = re.compile(r'\$\{([^}]+)\}')
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    msg = f"JSON decode error in file '{fname}': {e}"
                    errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
                    continue
            if not isinstance(data, dict):
                msg = f"Configuration in file '{fname}' is not a JSON object (dict)."
                errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
                continue
            # Apply overrides if provided
            if overrides:
                if not isinstance(overrides, dict):
                    msg = f"Overrides provided for file '{fname}' are not a dict."
                    errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
                else:
                    data.update(overrides)
            # Resolve environment variables if requested
            if resolve_env:
                def resolve_value(val):
                    if isinstance(val, str):
                        def repl(match):
                            var = match.group(1)
                            return os.getenv(var, match.group(0))
                        return env_pattern.sub(repl, val)
                    return val
                # Recursively resolve in dict
                def resolve_dict(d):
                    for k, v in d.items():
                        if isinstance(v, dict):
                            resolve_dict(v)
                        else:
                            d[k] = resolve_value(v)
                resolve_dict(data)
            configs[fname] = data
        except FileNotFoundError:
            msg = f"Configuration file '{fname}' not found."
            errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
        except Exception as e:
            msg = f"Unexpected error loading file '{fname}': {e}"
            errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. If ``obj`` is not a string,
    it is returned unchanged.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Could not encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate input
        if values is None:
            raise TypeError("values must be an iterable of strings, got None")
        if isinstance(values, str):
            raise TypeError("values must be an iterable of strings, not a single string")
        try:
            iterator = iter(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        parsed_bookmarks = []
        for raw in iterator:
            try:
                if not isinstance(raw, str):
                    continue
                raw = raw.strip()
                if not raw:
                    continue
                # Expected format: title|url|tags (tags optional, comma separated)
                parts = raw.split("|", 2)
                if len(parts) < 2:
                    # Not enough parts to form a bookmark; skip
                    continue
                title = parts[0].strip()
                url = parts[1].strip()
                tags = []
                if len(parts) == 3:
                    tags_str = parts[2].strip()
                    if tags_str:
                        tags = [t.strip() for t in tags_str.split(",") if t.strip()]
                # Attempt to create a Bookmark instance if available
                try:
                    BookmarkCls = getattr(cls, "Bookmark", None)
                    if BookmarkCls is not None:
                        bookmark = BookmarkCls(title=title, url=url, tags=tags)
                    else:
                        # Fallback to a simple dict representation
                        bookmark = {"title": title, "url": url, "tags": tags}
                except Exception:
                    # If Bookmark construction fails, use dict
                    bookmark = {"title": title, "url": url, "tags": tags}
                parsed_bookmarks.append(bookmark)
            except Exception:
                # Skip any entry that causes an unexpected error
                continue

        # Create the Bookmarks instance
        try:
            return cls(parsed_bookmarks)
        except Exception as exc:
            raise ValueError(f"Failed to create Bookmarks instance: {exc}") from exc

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Validate arguments
    if not isinstance(recompute, bool):
        raise TypeError("recompute must be a bool")
    if other is not None and not isinstance(other, (int, float)):
        raise TypeError("other must be a float or None")

    # Helper to compute the integral of the histogram
    def _compute_integral():
        try:
            counts = self._counts
            edges = self._bin_edges
        except AttributeError:
            raise AttributeError(
                "Histogram object must have _counts and _bin_edges attributes"
            )
        if not isinstance(counts, (list, tuple)):
            raise TypeError("_counts must be a list or tuple")
        if not isinstance(edges, (list, tuple)):
            raise TypeError("_bin_edges must be a list or tuple")
        if len(edges) < 2:
            return 0.0
        widths = [edges[i + 1] - edges[i] for i in range(len(edges) - 1)]
        return sum(c * w for c, w in zip(counts, widths))

    # If no new scale is requested, return the current scale
    if other is None:
        if recompute or getattr(self, "_scale", None) is None:
            self._scale = _compute_integral()
        return self._scale

    # Rescaling requested
    if getattr(self, "_scale", None) is None or recompute:
        self._scale = _compute_integral()

    if self._scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    factor = other / self._scale
    try:
        # Apply the scaling factor to all bin contents
        self._counts = [c * factor for c in self._counts]
    except Exception as exc:
        raise RuntimeError("Failed to rescale histogram") from exc

    self._scale = other
    return self._scale

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale is requested
    if other is None:
        return getattr(self, "_scale", None)

    # Validate the new scale
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Compute scaling factor
    factor = other / current_scale

    # Rescale the last coordinate of each data point
    data = getattr(self, "_data", None)
    if data is not None:
        # Handle list/tuple of points
        if isinstance(data, (list, tuple)):
            new_data = []
            for point in data:
                if isinstance(point, (list, tuple)):
                    # Convert to list for mutation
                    lst = list(point)
                    if lst:
                        lst[-1] = lst[-1] * factor
                    new_data.append(type(point)(lst))
                else:
                    # If point is not a sequence, leave unchanged
                    new_data.append(point)
            # Preserve original type
            if isinstance(data, list):
                self._data = new_data
            else:
                self._data = type(data)(new_data)
        # Handle numpy-like arrays if they support slicing
        elif hasattr(data, "__getitem__") and hasattr(data, "__setitem__"):
            try:
                # Attempt to rescale the last column
                data[:, -1] = data[:, -1] * factor
            except Exception:
                # Fallback: iterate if possible
                try:
                    for i in range(len(data)):
                        data[i][-1] = data[i][-1] * factor
                except Exception:
                    pass

    # Rescale errors if present
    errors = getattr(self, "_errors", None)
    if errors is not None:
        if isinstance(errors, (list, tuple)):
            new_errors = []
            for err in errors:
                if isinstance(err, (list, tuple)):
                    new_errors.append(type(err)([e * factor for e in err]))
                else:
                    new_errors.append(err * factor)
            if isinstance(errors, list):
                self._errors = new_errors
            else:
                self._errors = type(errors)(new_errors)
        elif hasattr(errors, "__getitem__") and hasattr(errors, "__setitem__"):
            try:
                errors[:] = [e * factor for e in errors]
            except Exception:
                pass

    # Update the stored scale
    self._scale = other
    return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram-like object to a graph representation.

    Parameters
    ----------
    hist : object
        Histogram-like object. It must provide an iterable of bins. Each bin
        should expose ``left``, ``right`` and ``content`` attributes, or be a
        tuple/list/dict with keys/indices ``0``/``1``/``2`` for left, right
        and content respectively.
    make_value : callable, optional
        Function that transforms a bin's content into the graph's y-values.
        It receives a single argument (the bin content) and should return
        either a scalar or a tuple/list of scalars. If omitted, the bin
        content itself is used.
    get_coordinate : {"left", "right", "middle"}, default "left"
        Determines which coordinate of the bin is used as the graph's x-value.
    field_names : tuple of str, default ("x", "y")
        Names of the fields in the resulting graph points. The first name
        corresponds to the x-coordinate; the remaining names correspond to the
        values returned by ``make_value``. The number of names must match the
        dimensionality of the graph.
    scale : bool or any, default None
        If ``True``, the graph inherits the histogram's ``scale`` attribute.
        Otherwise, the provided value is used as the graph's scale.

    Returns
    -------
    dict
        A dictionary with keys ``points`` (a list of point dictionaries) and
        ``scale`` (the graph's scale). Each point dictionary contains the
        fields specified by ``field_names``.
    """
    # Validate get_coordinate
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Validate field_names
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple")
    if not all(isinstance(name, str) for name in field_names):
        raise TypeError("all field_names must be strings")
    if len(field_names) < 2:
        raise ValueError("field_names must contain at least two names")

    # Resolve bins from hist
    if hasattr(hist, "bins"):
        bins_iter = hist.bins
    elif isinstance(hist, dict) and "bins" in hist:
        bins_iter = hist["bins"]
    else:
        # Assume hist itself is an iterable of bins
        bins_iter = hist

    # Ensure bins_iter is iterable
    try:
        iter(bins_iter)
    except TypeError:
        raise TypeError("hist must provide an iterable of bins")

    points = []

    for bin_ in bins_iter:
        # Extract left, right, content
        try:
            left = bin_.left
            right = bin_.right
            content = bin_.content
        except AttributeError:
            # Try tuple/list/dict
            if isinstance(bin_, (tuple, list)):
                if len(bin_) < 3:
                    raise ValueError("bin tuple/list must have at least 3 elements")
                left, right, content = bin_[0], bin_[1], bin_[2]
            elif isinstance(bin_, dict):
                try:
                    left = bin_["left"]
                    right = bin_["right"]
                    content = bin_["content"]
                except KeyError:
                    raise ValueError("bin dict must contain 'left', 'right', and 'content' keys")
            else:
                raise TypeError("Each bin must have left/right/content attributes or be a tuple/list/dict")

        # Determine x-coordinate
        if get_coordinate == "left":
            x_coord = left
        elif get_coordinate == "right":
            x_coord = right
        else:  # middle
            x_coord = (left + right) / 2

        # Compute y-values
        if make_value is None:
            y_val = content
        else:
            try:
                y_val = make_value(content)
            except Exception as exc:
                raise ValueError(f"make_value raised an exception: {exc}") from exc

        # Build point dictionary
        if isinstance(y_val, (tuple, list)):
            if len(y_val) != len(field_names) - 1:
                raise ValueError(
                    f"make_value returned a tuple/list of length {len(y_val)} "
                    f"but field_names expects {len(field_names)-1} y-values"
                )
            point = {field_names[0]: x_coord}
            for name, val in zip(field_names[1:], y_val):
                point[name] = val
        else:
            if len(field_names) != 2:
                raise ValueError(
                    "make_value returned a single value but field_names length is not 2"
                )
            point = {field_names[0]: x_coord, field_names[1]: y_val}

        points.append(point)

    # Construct graph dictionary
    graph = {"points": points}

    # Determine scale
    if scale is True:
        try:
            graph["scale"] = hist.scale
        except AttributeError:
            graph["scale"] = None
    elif scale is not None:
        graph["scale"] = scale
    else:
        graph["scale"] = None

    return graph

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not isinstance(bases, (tuple, list)):
        raise TypeError("bases must be a tuple or list of base classes")
    if len(bases) == 0:
        return type
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")
    # Determine metaclasses of the bases
    base_mcs = [type(base) for base in bases]
    # If an explicit metaclass is provided, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a type")
        for mc in base_mcs:
            if not issubclass(explicit_mc, mc):
                raise TypeError(
                    f"explicit metaclass {explicit_mc.__name__} is not a subclass of base metaclass {mc.__name__}"
                )
        return explicit_mc
    # No explicit metaclass: find the most derived metaclass
    chosen = base_mcs[0]
    for mc in base_mcs[1:]:
        if issubclass(chosen, mc):
            # chosen is more derived; keep it
            pass
        elif issubclass(mc, chosen):
            chosen = mc
        else:
            raise TypeError(
                f"metaclass conflict: {chosen.__name__} vs {mc.__name__}"
            )
    return chosen

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Ensure required attributes exist
        if not hasattr(self, 'freq_map') or not hasattr(self, 'key_map') or not hasattr(self, 'min_freq'):
            raise AttributeError("LFU cache missing required attributes")
        freq_map = self.freq_map
        key_map = self.key_map
        min_freq = self.min_freq

        # If the cache is empty, raise KeyError
        if not freq_map:
            raise KeyError("Cache is empty")

        # If min_freq is not present in freq_map, find the actual minimum
        if min_freq not in freq_map:
            min_freq = min(freq_map.keys())
            self.min_freq = min_freq

        keys_at_min = freq_map[min_freq]

        # Pop the least recently used key among those with the minimum frequency
        try:
            # Try OrderedDict style popitem(last=False)
            key, _ = keys_at_min.popitem(last=False)
        except TypeError:
            # Fallback for plain dict or other mapping types
            key, _ = keys_at_min.popitem()

        # Retrieve the value and frequency from key_map
        if key not in key_map:
            raise KeyError(f"Key {key} not found in key_map")
        value, freq = key_map.pop(key)

        # If the bucket for min_freq is now empty, remove it and update min_freq
        if not keys_at_min:
            del freq_map[min_freq]
            if freq_map:
                self.min_freq = min(freq_map.keys())
            else:
                self.min_freq = None

        return key, value
    except KeyError:
        raise
    except AttributeError:
        raise
    except Exception as e:
        raise RuntimeError(f"Error in popitem: {e}") from e

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # Ensure the cache has a tail node to pop
        if not hasattr(self, "tail") or self.tail is None:
            raise KeyError("popitem from an empty LRUCache")

        node = self.tail
        key = node.key
        value = node.value

        # Remove the node from the doubly‑linked list
        if node.prev:
            node.prev.next = None
            self.tail = node.prev
        else:
            # This was the only node in the list
            self.head = None
            self.tail = None

        # Clean up the node's pointers
        node.prev = None
        node.next = None

        # Remove the key from the internal dictionary if it exists
        if hasattr(self, "cache") and key in self.cache:
            del self.cache[key]

        return (key, value)

    except KeyError:
        # Re‑raise KeyError to signal an empty cache
        raise
    except Exception as exc:
        # Wrap any other exception in a RuntimeError for clarity
        raise RuntimeError(f"Error in popitem: {exc}") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Attempt to pop from an internal mapping if present
        if hasattr(self, "_data"):
            try:
                # Prefer the most recently used (last) item
                return self._data.popitem(last=True)
            except TypeError:
                # Fallback if the mapping does not support the `last` argument
                return self._data.popitem()
        # Fallback to the base class implementation
        return super().popitem()
    except KeyError:
        # No items to pop
        raise KeyError("popitem(): dictionary is empty")
    except Exception as exc:
        # Unexpected runtime issue
        raise RuntimeError(f"Unexpected error in popitem: {exc}") from exc

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches 'IN' keyword followed by optional whitespace and a parenthesized list.
        return re.compile(r'\bIN\s*\(([^)]*)\)', re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Could not compile in-style regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        # Attempt to instantiate the converter with default arguments.
        converter = _converting._Converter()
    except TypeError as exc:
        # Likely the converter requires arguments that were not provided.
        raise TypeError(
            "Failed to instantiate _converting._Converter: missing required arguments"
        ) from exc
    except Exception as exc:
        # Catch any other unexpected errors during instantiation.
        raise RuntimeError(
            "Unexpected error while creating _converting._Converter"
        ) from exc
    return converter

def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    See the module documentation for details.
    """
    import datetime
    import re
    from dateutil.tz import tzutc, tzoffset

    # Accept a stream
    if hasattr(dt_str, "read"):
        dt_str = dt_str.read()

    if not isinstance(dt_str, str):
        raise TypeError("dt_str must be a string or stream")

    dt_str = dt_str.strip()
    if not dt_str:
        raise ValueError("empty datetime string")

    # Split date and time
    if 'T' in dt_str:
        date_part, time_part = dt_str.split('T', 1)
    else:
        # Allow space separator as a fallback
        if ' ' in dt_str:
            date_part, time_part = dt_str.split(' ', 1)
        else:
            date_part, time_part = dt_str, None

    # Parse date
    date_obj = None
    # Week-based date
    week_re = re.compile(r'^(?P<year>\d{4})-?W(?P<week>\d{2})(?:-?(?P<weekday>\d))?$')
    m = week_re.match(date_part)
    if m:
        year = int(m.group('year'))
        week = int(m.group('week'))
        weekday = int(m.group('weekday')) if m.group('weekday') else 1
        try:
            date_obj = datetime.date.fromisocalendar(year, week, weekday)
        except Exception as e:
            raise ValueError(f"Invalid ISO week date: {date_part}") from e
    else:
        # Regular date
        date_re = re.compile(r'^(?P<year>\d{4})-?(?P<month>\d{2})?(-?(?P<day>\d{2}))?$')
        m = date_re.match(date_part)
        if not m:
            raise ValueError(f"Invalid date format: {date_part}")
        year = int(m.group('year'))
        month = int(m.group('month')) if m.group('month') else 1
        day = int(m.group('day')) if m.group('day') else 1
        try:
            date_obj = datetime.date(year, month, day)
        except Exception as e:
            raise ValueError(f"Invalid date: {date_part}") from e

    # If time part is present, ensure date is complete
    if time_part:
        if not (len(date_part) >= 8 or week_re.match(date_part)):
            # Incomplete date with time is not allowed
            raise ValueError("Incomplete date cannot be combined with time")

    # Parse time and timezone
    hour = minute = second = microsecond = 0
    tzinfo = None

    if time_part:
        # Separate timezone
        tz_str = None
        if time_part.endswith('Z'):
            tz_str = 'Z'
            time_str = time_part[:-1]
        else:
            # Find last '+' or '-' that is not part of the time
            idx = None
            for i, ch in enumerate(time_part):
                if ch in '+-':
                    idx = i
                    break
            if idx is not None:
                tz_str = time_part[idx:]
                time_str = time_part[:idx]
            else:
                time_str = time_part

        # Normalize decimal separator
        time_str = time_str.replace(',', '.')
        if '.' in time_str:
            int_part, frac_part = time_str.split('.', 1)
        else:
            int_part, frac_part = time_str, None

        # Remove any remaining separators
        int_part = int_part.replace(':', '')

        if len(int_part) == 2:
            hour = int(int_part)
        elif len(int_part) == 4:
            hour = int(int_part[:2])
            minute = int(int_part[2:4])
        elif len(int_part) == 6:
            hour = int(int_part[:2])
            minute = int(int_part[2:4])
            second = int(int_part[4:6])
        else:
            raise ValueError(f"Invalid time format: {time_part}")

        if frac_part:
            # Pad or truncate to 6 digits
            frac = (frac_part + '000000')[:6]
            microsecond = int(frac)

        # Handle 24:00:00
        if hour == 24:
            if minute != 0 or second != 0:
                raise ValueError("24 hour must have 00 minutes and 00 seconds")
            hour = 0
            date_obj += datetime.timedelta(days=1)

        # Parse timezone
        if tz_str:
            if tz_str == 'Z':
                tzinfo = tzutc()
            else:
                sign = 1 if tz_str[0] == '+' else -1
                tz_body = tz_str[1:]
                if ':' in tz_body:
                    hh, mm = tz_body.split(':')
                elif len(tz_body) == 4:
                    hh, mm = tz_body[:2], tz_body[2:]
                elif len(tz_body) == 2:
                    hh, mm = tz_body, '00'
                else:
                    raise ValueError(f"Invalid timezone format: {tz_str}")
                offset = sign * (int(hh) * 3600 + int(mm) * 60)
                tzinfo = tzoffset(None, offset) if offset != 0 else tzutc()

    # Build datetime
    try:
        dt = datetime.datetime(
            date_obj.year, date_obj.month, date_obj.day,
            hour, minute, second, microsecond, tzinfo=tzinfo
        )
    except Exception as e:
        raise ValueError(f"Failed to construct datetime from components") from e

    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Handle None or non-object inputs gracefully
        if request is None:
            return False

        # Helper to get attribute or dict key safely
        def get_value(obj, key):
            if isinstance(obj, dict):
                return obj.get(key)
            return getattr(obj, key, None)

        # 1. Check public message
        public_msg = get_value(request, 'public_message')
        if public_msg and isinstance(public_msg, str) and 'diaspora' in public_msg.lower():
            return True

        # 2. Check private message
        private_msg = get_value(request, 'private_message')
        if private_msg and isinstance(private_msg, str) and 'diaspora' in private_msg.lower():
            return True

        # 3. Check legacy payload
        payload = get_value(request, 'payload')
        if payload:
            if isinstance(payload, dict) and 'diaspora' in payload:
                return True
            if isinstance(payload, str) and 'diaspora' in payload.lower():
                return True

    except Exception:
        # Any unexpected error should result in a safe False
        return False

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            if "type" in request and "content" in request:
                req_type = request["type"]
                if isinstance(req_type, str) and (
                    req_type.startswith("m.") or req_type.startswith("org.matrix.")
                ):
                    return True
            return False

        # Handle object-like requests with attributes
        if hasattr(request, "type") and hasattr(request, "content"):
            req_type = getattr(request, "type")
            if isinstance(req_type, str) and (
                req_type.startswith("m.") or req_type.startswith("org.matrix.")
            ):
                return True

        return False
    except Exception:
        # Any unexpected error should result in a safe False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a datetime.datetime instance or an ISO‑formatted string.
    It returns the datetime in UTC as an ISO 8601 string ending with 'Z'.
    """
    # Validate input
    if dt is None:
        raise ValueError("dt cannot be None")

    # If a string is provided, try to parse it as ISO format
    if isinstance(dt, str):
        try:
            dt = datetime.datetime.fromisoformat(dt)
        except Exception as exc:
            raise ValueError(f"String dt must be in ISO format: {exc}") from exc

    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance or ISO string")

    # Ensure the datetime is timezone aware and in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)

    # Format as ISO 8601 with trailing 'Z'
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Add target and rel attributes to existing <a> tags
    def _add_attrs(match):
        tag = match.group(0)
        # Ensure the tag ends with '>'
        if not tag.endswith('>'):
            tag += '>'
        # Add target if missing
        if 'target=' not in tag.lower():
            tag = tag.rstrip('>') + ' target="_blank">'
        # Add rel if missing
        if 'rel=' not in tag.lower():
            tag = tag.rstrip('>') + ' rel="noopener noreferrer">'
        return tag

    a_tag_pattern = re.compile(r'<a\s+[^>]*href="[^"]+"[^>]*>', re.IGNORECASE)
    text = a_tag_pattern.sub(_add_attrs, text)

    # Linkify plain URLs
    url_pattern = re.compile(r'\b(https?://[^\s<]+)', re.IGNORECASE)

    def _linkify(match):
        url = match.group(1)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    # Avoid double-linking URLs that are already inside an <a> tag
    def _safe_linkify(match):
        start, end = match.span()
        # Check if the match is inside an <a> tag
        before = text.rfind('<a', 0, start)
        if before != -1:
            after = text.find('>', before)
            if after != -1 and after < start:
                # The URL is inside an existing <a> tag; leave it unchanged
                return match.group(0)
        return _linkify(match)

    text = url_pattern.sub(_safe_linkify, text)
    return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        # Ensure the input is a string
        if not isinstance(tag, str):
            return False

        # Strip leading/trailing whitespace
        tag = tag.strip()

        # Tag must not be empty
        if not tag:
            return False

        # Optional length constraint (e.g., max 30 characters)
        if len(tag) > 30:
            return False

        # Allowed characters: letters, digits, hyphen, underscore
        allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
        if not all(ch in allowed_chars for ch in tag):
            return False

        return True
    except Exception:
        # In case of any unexpected error, treat as invalid
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Return an empty dict for invalid or empty input
    if node is None:
        return {}
    try:
        # In ElementTree and lxml, iterating over the node yields its children
        children = list(node)
    except Exception:
        return {}
    result = {}
    for child in children:
        # Ensure the child has a tag attribute
        tag = getattr(child, 'tag', None)
        if tag is not None:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    url = url.strip()
    if not url:
        raise ValueError("url cannot be empty")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Determine the document path
    if document_path is None:
        document_path = "/nodeinfo/2.0"
    else:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        document_path = document_path.strip()
        if not document_path:
            document_path = "/nodeinfo/2.0"

    # Build the full href
    base = url.rstrip("/")
    path = document_path.lstrip("/")
    href = f"{base}/{path}"

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    doc = document.strip()
    # Try JSON format first
    try:
        json = __import__('json')
        data = json.loads(doc)
        if isinstance(data, dict):
            subject = data.get('subject')
            aliases = data.get('aliases', [])
            links = data.get('links', [])
            return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception:
        pass
    # Fallback to XRD (XML) format
    try:
        ET = __import__('xml.etree.ElementTree')
        root = ET.fromstring(doc)
        # Handle optional namespace
        ns = {}
        if root.tag.startswith('{'):
            uri, _, _ = root.tag[1:].partition('}')
            ns = {'ns': uri}
            subject_elem = root.find('ns:Subject', ns)
            alias_elems = root.findall('ns:Alias', ns)
            link_elems = root.findall('ns:Link', ns)
        else:
            subject_elem = root.find('Subject')
            alias_elems = root.findall('Alias')
            link_elems = root.findall('Link')
        subject = subject_elem.text if subject_elem is not None else None
        aliases = [e.text for e in alias_elems if e.text]
        links = []
        for le in link_elems:
            link = {k: v for k, v in le.attrib.items()}
            links.append(link)
        return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception:
        pass
    # If all parsing attempts fail, return an empty dict
    return {}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Basic validation of the handle
    if not isinstance(handle, str):
        return {}
    handle = handle.strip()
    if not handle:
        return {}
    if '@' not in handle:
        return {}
    try:
        local_part, domain = handle.rsplit('@', 1)
    except ValueError:
        return {}
    if not domain:
        return {}
    # Construct the webfinger URL
    try:
        import urllib.request
        import urllib.parse
        import json
        from urllib.error import URLError, HTTPError
    except Exception:
        # If imports fail, return empty dict
        return {}
    resource = f'acct:{handle}'
    query = urllib.parse.urlencode({'resource': resource})
    url = f'https://{domain}/.well-known/webfinger?{query}'
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return {}
            content_type = response.headers.get('Content-Type', '')
            data = response.read()
            try:
                # Decode bytes to string
                text = data.decode('utf-8')
                # Parse JSON
                result = json.loads(text)
                if isinstance(result, dict):
                    return result
                else:
                    return {}
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {}
    except (URLError, HTTPError, ValueError):
        return {}
    except Exception:
        return {}
    return {}

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file paths from the given directories that match the spec_option.

    Parameters
    ----------
    settings_dirs : list or tuple
        A list of directory paths to search for files.
    spec_option : str
        A file extension or suffix to filter files. If empty, all files are returned.

    Returns
    -------
    list
        Sorted list of full file paths that match the spec_option.

    Raises
    ------
    TypeError
        If `settings_dirs` is not a list/tuple or `spec_option` is not a string.
    """
    # Validate input types
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")

    import os

    matched_files = []

    for dir_path in settings_dirs:
        # Skip non-string entries
        if not isinstance(dir_path, str):
            continue

        # Skip if the directory does not exist
        if not os.path.isdir(dir_path):
            continue

        try:
            for root, _, files in os.walk(dir_path):
                for filename in files:
                    if spec_option:
                        if filename.endswith(spec_option):
                            matched_files.append(os.path.join(root, filename))
                    else:
                        matched_files.append(os.path.join(root, filename))
        except Exception:
            # If any error occurs while walking a directory, skip it
            continue

    return sorted(matched_files)

@classmethod
